    if (!(ev.source_ids || []).some(id => sourceIds.has(id))) {
      errors.push({ stage: 'TRACEABILITY_CHECK', error_type: 'untraceable_evidence', message: `${ev.evidence_id} does not reference a known source` });
    }
  }
